import { describe, expect, it } from "vitest";
import { createApp } from "/work/src/app.ts";

const fixedClock = () => new Date("2026-10-01T08:00:00Z");

function setup() {
  const app = createApp({ clock: fixedClock });
  app.request("POST", "/coupons", {
    code: "SAVE20",
    type: "PERCENT",
    value: 20,
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
  });
  return app;
}

describe("apply-coupon", () => {
  it("percent", () => {
    const app = setup();
    app.request("POST", "/orders", { customer: "a", amountCents: 12000 });
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 2400, finalAmountCents: 9600, couponCode: "SAVE20" });
    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 1 });
  });

  it("fixed with cap and min", () => {
    const app = createApp({ clock: fixedClock });
    app.request("POST", "/coupons", {
      code: "FLAT50",
      type: "FIXED",
      value: 5000,
      maxDiscountCents: 3000,
      minAmountCents: 4000,
      validFrom: "2026-01-01T00:00:00Z",
      validUntil: "2027-01-01T00:00:00Z",
    });
    app.request("POST", "/orders", { customer: "a", amountCents: 10000 });
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "FLAT50" });
    expect(res.body).toMatchObject({ discountCents: 3000, finalAmountCents: 7000 });
  });

  it("does not go below zero", () => {
    const app = createApp({ clock: fixedClock });
    app.request("POST", "/coupons", {
      code: "FLAT",
      type: "FIXED",
      value: 99999,
      validFrom: "2026-01-01T00:00:00Z",
      validUntil: "2027-01-01T00:00:00Z",
    });
    app.request("POST", "/orders", { customer: "a", amountCents: 500 });
    const res = app.request("POST", "/orders/1/apply-coupon", { couponCode: "FLAT" });
    expect(res.body).toMatchObject({ discountCents: 500, finalAmountCents: 0 });
  });

  it("errors", () => {
    const app = setup();
    app.request("POST", "/orders", { customer: "a", amountCents: 12000 });
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "NOPE" }).status).toBe(404);
    expect(app.request("POST", "/orders/1/apply-coupon", {}).status).toBe(400);
    app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" });
    expect(app.request("POST", "/orders/1/apply-coupon", { couponCode: "SAVE20" }).status).toBe(409);
    app.request("POST", "/orders", { customer: "b", amountCents: 100 });
    app.request("POST", "/orders/2/pay");
    expect(app.request("POST", "/orders/2/apply-coupon", { couponCode: "SAVE20" }).status).toBe(409);
  });
});

